"""Read-only results reconciliation; no model calls, training, or reselection."""
import json,hashlib,shutil
from pathlib import Path
from data import ROOT,PARENT,RESULTS,save

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 freeze=json.loads((ROOT/'freeze.json').read_text(encoding='utf-8'));selection=json.loads((ROOT/'selection.json').read_text(encoding='utf-8'));source=Path(__file__).parent
 assert all(sha(source/name)==h for name,h in freeze['sources'].items());assert sha(source/'protocol.json')==freeze['protocolSha256'];assert sha('/workspace/scratch/ocr-production-development-20261015-v1/models/ascii-rec.onnx')=='9dd3ed77db4f2af171cf434d200c666033c9bdfe5f33446bc47dbfecac90d703';assert sha('/workspace/scratch/ocr-frozen-20261013/v6-medium.onnx')==freeze['japanesePrimarySha256']
 for candidate in [selection['activeBaseline']]+selection['candidates']:assert sha(candidate['path'])==candidate['sha256']
 fresh_path=RESULTS/'fresh-comparison.json';fresh=json.loads(fresh_path.read_text(encoding='utf-8')) if fresh_path.exists() else None
 active=selection['activeBaseline']['metrics'];chosen=selection['selected'];cm=chosen['metrics'];trained=chosen['epoch']>0
 def row(label,m):return f"| {label} | {m['exact']}/{m['positiveRows']} | {100*m['cer']:.3f}% | {100*m['codeMetrics']['cer']:.3f}% | {100*m['groups']['natural']['cer']:.3f}% | {m['correctAccepted']}/{m['incorrectAccepted']} | {m['negativeAccepted']}/{m['negativeRows']} |"
 text='# English V5 confusion continuation v2\n\n'+('A trained candidate passed the frozen development comparison. ' if trained else 'The original active model remains selected; the bounded continuation did not meet the frozen practical improvement criteria. ')
 text+='The architecture foundation is official PP-OCRv5 English full438. Actual initialization **and teacher** are the previously adapted active font-balanced epoch-4 checkpoint SHA `7313bee5dabf17998010c6f47844fe80649744b03c0366af05c627fc47314547`, matching active ONNX SHA `9dd3ed77db4f2af171cf434d200c666033c9bdfe5f33446bc47dbfecac90d703`; the unadapted official weights are not this trial’s initializer or teacher.\n\nThis is a fictional synthetic crop experiment. It does not measure real timetable, complete-document, or native combined-route accuracy. No product model was replaced or published, and iOS was not edited.\n\n| Comparison | Raw exact | Whole CER | Code CER | Natural CER | Correct/wrong accepted | Negative accepted |\n| --- | --- | --- | --- | --- | --- | --- |\n'+row('New development active',active)+'\n'
 for c in selection['candidates']:text+=row('New development '+c['name'],c['metrics'])+'\n'
 if fresh:text+='\n| Comparison | Raw exact | Whole CER | Code CER | Natural CER | Correct/wrong accepted | Negative accepted |\n| --- | --- | --- | --- | --- | --- | --- |\n'+row('Independent fresh active',fresh['active'])+'\n'+row('Independent fresh selected',fresh['candidate'])+'\n'
 text+='\nA read-only normalized-input audit found two shared all-white blank controls between train and development; no positive input overlaps. These controls are disclosed and development is not claimed independent final evidence. Fresh generation excludes every train/development PNG and normalized-input hash, including these blanks.\n\nDevelopment is consumed development. Fresh fonts/seed/literals are separate and are generated only after selection hash is fixed. Wrong accept zero is not required; CER, gains, regressions, natural-text retention, wrong accepts, negative categories, confidence/review counts and original-pixel padding refusal are reported separately. Uncalibrated confidence/reject scores do not prove source completeness. Japanese-primary byte identity is preserved; CJK negatives do not establish Japanese recognition quality.\n\n'
 if fresh:text+=f"Fresh raw improvements: {len(fresh['gains'])}; regressions: {len(fresh['regressions'])}. Original active ONNX versus matching Torch decisions/intervals/padding: {fresh['activeOriginalOnnxTorchDecisionParity']} across {fresh['activeParityRows']} rows. Portable-export usefulness: {fresh['promisingForPortableExport']}. No further training/reselection follows fresh.\n\n"
 else:text+='No fresh images were generated or opened because no trained candidate won development. No new ONNX or CoreML was exported.\n\n'
 diagnosis=json.loads((RESULTS/'diagnosis.json').read_text(encoding='utf-8'));d=diagnosis['conditions'];text+=f"Correct raw lines requiring diagnostic review: development {len(d['active-baseline']['correctNeedsReview'])}→{len(d[chosen['name']]['correctNeedsReview'])}. Development paired gains/regressions are recorded in diagnosis.json. Literata development regresses raw79→78/96, whole CER1.488→1.637%, code errors12→15; its wrong accepts5→8. This subgroup regression is retained despite aggregate selection.\n\n"
 if fresh:text+=f"Fresh correct lines requiring review: {len(d['fresh-active']['correctNeedsReview'])}→{len(d['fresh-candidate']['correctNeedsReview'])}. I/l/1/O/0-confusion wrong rows9→6, but accepted confusable wrong rows2→2. Fraunces fresh regresses raw90→89/96 and code errors2→5; SplineSansMono91→96, MartianMono93→93, Newsreader86→90. Fresh blank16 has three repeated normalized all-white pairs, no positive contradictions; old/train/dev/root-oracle literal/PNG/input overlaps are all zero (fresh-corpus-exclusion-audit.json).\n\n"
 portable=RESULTS/'portable-v2/summary.json'
 if portable.exists():
  ps=json.loads(portable.read_text(encoding='utf-8'));text+=f"Standard ONNX FP32 exported: `{ps['onnxOutsideGit']}`, SHA `{ps['onnxSha256']}`. Standard domains only, 12 dynamic batch/width shapes, and {ps['developmentRows']} consumed-dev Torch/ONNX text/interval/padding/accept decisions all agree: {ps['allDevelopmentTextIntervalPaddingAcceptEqual']}. Selected pre-export Torch raw reproduces exactly. Numeric FP32 confidence differences are retained in the fidelity receipt; this is not a bitwise-identity claim. CoreML/iPhone inference was not attempted. Parent actual native combined-route and full-document assessment remains necessary.\n\n"
 text+=f"Training: {selection['trainingSeconds']:.2f} seconds; cache: {selection['cacheSeconds']:.2f} seconds; peak own RSS {selection['peakRssMiB']:.2f} MiB; budget stop: {selection['budgetStopped']}. CPU 2 threads, batch 2, two epochs. Active-checkpoint SHA `{selection['activeBaseline']['sha256']}`; selected SHA `{chosen['sha256']}`.\n\nInitially registered training sources and protocol remain byte-identical to the training freeze. The initial fresh launcher hit a parent/sibling train.py import collision before freeze, image generation or model calls; explicit sibling-file import repaired that evaluation launcher, and its first failure log is retained. Original assets/checkpoints/cache/raw outputs are retained externally. Corpus, exclusion, initialization, contradiction and source audits are in the adjacent receipts. The extra-code-literal audit verifies no overlap with old-v1/old-v2/current-root code oracles before optimization. Standard model weights/images/cache remain outside Git.\n"
 (RESULTS/'README.md').write_text(text,encoding='utf-8',newline='\n')
 summary={'selected':chosen['name'],'selectedSha256':chosen['sha256'],'trainedCandidateSelected':trained,'freshOpened':fresh is not None,'freshPromisingForExport':fresh['promisingForPortableExport'] if fresh else None,'initialFrozenSourceAndProtocolUnchanged':True,'activeOriginalOnnxUnchanged':True,'japanesePrimaryUnchanged':True,'ownScratchBytes':sum(p.stat().st_size for p in PARENT.rglob('*') if p.is_file()),'freeDiskBytes':shutil.disk_usage(PARENT).free,'trainingSeconds':selection['trainingSeconds'],'cacheSeconds':selection['cacheSeconds'],'peakTrainingRssMiB':selection['peakRssMiB'],'childCommitOrPush':False,'iosEdited':False,'productActivated':False,'privateDataUsed':False,'sourceSha256':sha(Path(__file__))};save(RESULTS/'closure.json',summary);print(json.dumps(summary))
if __name__=='__main__':main()
